        G = [[0] * n for _ in range(n)]
        degree = 2
        if n % degree != 0:
            return None, None
        for i in range(n // degree):
            for j in range(degree):
                u = i * degree + j
                v = (i + 1) % (n // degree) * degree + (j + 1) % degree
                G[u][v] = 1
                G[v][u] = 1
        return G, degree

    def communication_complexity_rank(G):
        n = len(G)
        degree = sum(sum(row) for row in G) // n
        if degree == 0:
            return 0
        rank = 0
        visited = [False] * n
        stack = []
        for i in range(n):
            if not visited[i]:
                stack.append(i)
                while stack:
                    u = stack.pop()
                    if not visited[u]:
                        visited[u] = True
                        rank += 1
                        for v in range(n):
                            if G[u][v] == 1 and not visited[v]:
                                stack.append(v)
        return rank

